import test from 'node:test';
import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import { createRequire } from 'node:module';

// The Dialogue Editor's runtime layer (bladefall-text.js) and its catalog
// (bladefall-text-catalog.js, generated by scripts/build-text-catalog.mjs).
const require = createRequire(import.meta.url);
const read = f => readFileSync(new URL('../public/' + f, import.meta.url), 'utf8');

function freshText(){
  const store = new Map();
  globalThis.localStorage = { getItem:k => store.has(k) ? store.get(k) : null, setItem:(k, v) => store.set(k, String(v)), removeItem:k => store.delete(k) };
  for(const f of ['bladefall-text.js', 'bladefall-dialogue.js']) delete require.cache[require.resolve('../public/' + f)];
  const D = require('../public/bladefall-dialogue.js'); globalThis.BladefallDialogue = D;
  const T = require('../public/bladefall-text.js');
  return { T, D, store };
}

test('an edit replaces the whole line wherever it is shown, and nothing else', () => {
  const { T } = freshText();
  assert.equal(T.apply('The reserve is sealed.'), 'The reserve is sealed.', 'no edits: text passes through');
  T.load({ 'The reserve is sealed.':'Locked tight.', 'Vey':'Veyan', 'Leave.':'Go.', 'Keep it dry. I haven’t got a spare.':'Keep it dry, mind.' });
  assert.equal(T.apply('The reserve is sealed.'), 'Locked tight.');
  assert.equal(T.apply('<b>MILEKEEPER’S RESERVE</b><br>The reserve is sealed.'), '<b>MILEKEEPER’S RESERVE</b><br>Locked tight.', 'each run between tags');
  assert.equal(T.apply('<b>MARA</b><br>“Keep it dry. I haven’t got a spare.”'), '<b>MARA</b><br>“Keep it dry, mind.”', 'quotes around speech are kept');
  assert.equal(T.apply('<b>VEY · STANDARD-BEARER</b>'), '<b>VEYAN · STANDARD-BEARER</b>', 'an ALL-CAPS display of a name, and " · " parts');
  assert.equal(T.apply('line one\n\n“Keep it dry. I haven’t got a spare.”'), 'line one\n\n“Keep it dry, mind.”', 'lines are matched one by one');
  assert.equal(T.apply('Leave.'), 'Go.'); assert.equal(T.apply('Leave now.'), 'Leave now.', 'short lines match only whole');
  assert.equal(T.apply('It’s: The reserve is sealed. Mind.'), 'It’s: Locked tight. Mind.', 'long originals also inside assembled lines');
  assert.equal(T.apply('<b>Vey &amp; co</b>'), '<b>Vey &amp; co</b>');
  assert.equal(T.apply('-12'), '-12');
  assert.equal(T.applyPlain('<not a tag> Leave.'), '<not a tag> Leave.');
});

test('fragment edits replace whole words only, and HTML stays escaped', () => {
  const { T } = freshText();
  T.load({ 'Fish & chips.':'Fish <and> chips.' }, { 'QUEST':'TASK', 'HITS':'STRIKES' });
  assert.equal(T.apply('<b style="color:#fff">QUEST · Kindling the Sky</b>'), '<b style="color:#fff">TASK · Kindling the Sky</b>');
  assert.equal(T.apply('12 HITS'), '12 STRIKES');
  assert.equal(T.apply('WHITSUN QUESTION'), 'WHITSUN QUESTION', 'not inside other words');
  assert.equal(T.apply('<i>Fish &amp; chips.</i>'), '<i>Fish &lt;and&gt; chips.</i>', 'decoded to match, re-escaped to show');
});

test('saved edits persist, BladefallDialogue ids still apply, and export/import round-trips with file:line', () => {
  const { T, D, store } = freshText();
  T.save({ 'The reserve is sealed.':'Locked tight.' }, { QUEST:'TASK' });
  assert.equal(T.isActive(), true);
  assert.equal(JSON.parse(store.get(T.KEY)).byText['The reserve is sealed.'], 'Locked tight.');
  D.save({ 'outskirts.mara.ask':'Edited ask.' });
  assert.equal(D.text('outskirts.mara.ask'), 'Edited ask.', 'the id store keeps working');
  T.load(); const base = D.ENTRIES['outskirts.mara.ask'].text;
  assert.equal(T.apply(base), 'Edited ask.', 'an id edit also maps its default text, for a game left open');
  const catalog = { entries:[{ text:'The reserve is sealed.', file:'public/index.html', line:10, kind:'annotation', region:'General' }] };
  const out = T.exportData(catalog);
  assert.equal(out.format, 'bladefall-text-overrides');
  assert.deepEqual(out.dialogue, { 'outskirts.mara.ask':'Edited ask.' });
  const row = out.text.find(r => r.original === 'The reserve is sealed.');
  assert.equal(row.file, 'public/index.html'); assert.equal(row.line, 10); assert.equal(row.edited, 'Locked tight.');
  assert.equal(out.text.find(r => r.original === 'QUEST').fragment, true);
  const second = freshText();
  const counts = second.T.importData(JSON.parse(JSON.stringify(out)));
  assert.deepEqual(counts, { dialogue:1, text:2 });
  assert.equal(second.T.apply('The reserve is sealed.'), 'Locked tight.');
  assert.equal(second.T.apply('QUEST · X'), 'TASK · X');
  assert.equal(second.D.text('outskirts.mara.ask'), 'Edited ask.');
  second.T.importData({ 'outskirts.vey.after':'Old editor file.' });
  assert.equal(second.D.text('outskirts.vey.after'), 'Old editor file.', 'the old editor’s {id:text} files still import');
  second.D.save({}); second.T.save({}, {});
  assert.equal(second.T.isActive(), false, 'reset all');
});

test('the catalog lists every kind of readable text with its file and line', () => {
  const C = require('../public/bladefall-text-catalog.js');
  assert.ok(C.count > 2000, 'thousands of strings, not a handful: ' + C.count);
  const has = (text, kind) => { const e = C.entries.find(x => x.text === text); assert.ok(e, 'missing: ' + text); if(kind) assert.equal(e.kind, kind, text); return e; };
  has('The coals are still warm. This camp was abandoned recently.', 'annotation');   // a place annotation
  has('The reserve is sealed.', 'annotation');
  has('Secure the counterweight', 'task');                                            // side-story task label
  has('Push the stone-filled cart onto the iron stop east of camp, then pull the brake handle.', 'task');
  has('Restore two measures of Blood.', 'description');                              // shop item
  has('Campaign discoveries are not saved from Level Select.', 'toast');
  has('His vision swims. The Knight rises beneath a sky he does not remember.');     // narration card
  has('You are the last Warden.');
  has('STAND ON A SURFACE TO SET A MOUTH', 'hud');
  has('Read the Sky-Well plaque in the Updrafts.', 'label');                          // quest objective
  has('The Outskirts');                                                                // stage name
  has('I’ll leave you to it.', 'reply');
  const D = require('../public/bladefall-dialogue.js');
  for(const id of Object.keys(D.ENTRIES)) assert.ok(C.entries.some(e => e.id === id), 'dialogue id kept: ' + id);
  for(const e of C.entries){
    assert.ok(e.file && e.places.length, 'every entry says where it lives: ' + e.text);
    assert.doesNotMatch(e.text, /<\/?[a-z][^>]*>/i, 'catalog text is what is shown, not markup: ' + e.text);
  }
});

test('the catalog is regenerated from the source (it may trail small edits, not the game)', async () => {
  const { build } = await import('../scripts/build-text-catalog.mjs');
  const fresh = build(), C = require('../public/bladefall-text-catalog.js');
  const have = new Set(C.entries.map(e => e.key));
  const found = fresh.filter(e => have.has(e.id ? 'id:' + e.id : 't:' + e.text)).length;
  assert.ok(found / fresh.length > 0.9, `catalog is stale: ${found}/${fresh.length} current strings listed — run node scripts/build-text-catalog.mjs`);
});

test('every display choke point applies edits, and the new files are shipped', () => {
  const index = read('index.html'), conversation = read('bladefall-conversation.js'), sw = read('sw.js'),
    deploy = readFileSync(new URL('../build-deploy.sh', import.meta.url), 'utf8'), editor = read('dialogue-editor.html');
  assert.match(conversation, /function show\(\{[^)]*\}(=\{\})?\)\{\n    if\(root\.BladefallText\)\{[^\n]*T\.applyPlain\(text\)[^\n]*label:T\.applyPlain\(c\.label\)/, 'one line at the top of show()');
  assert.match(index, /<script src="bladefall-dialogue\.js\?v=[\d.]+"><\/script>\n<script src="bladefall-text\.js\?v=[\d.]+"><\/script>/);
  assert.match(index, /if\(window\.BladefallText\)\{copy\.title=BladefallText\.applyPlain\(copy\.title\)/, 'annotations');
  assert.match(index, /if\(window\.BladefallText\)msg=BladefallText\.apply\(String\(msg\),true\);t\.innerHTML=msg/, 'toasts');
  assert.match(index, /BladefallText\.applyPlain\(String\(message\|\|''\)\)/, 'station notices');
  assert.match(index, /if\(window\.BladefallText\)html=BladefallText\.apply\(html,true\);[^\n]*\n  ovcard\.innerHTML=html/, 'overlay cards');
  for(const f of ['bladefall-text.js', 'bladefall-text-catalog.js']){
    assert.match(sw, new RegExp("'\\./" + f.replace('.', '\\.') + "\\?v=[\\d.]+'"), 'precached: ' + f);
    assert.match(deploy, new RegExp('^  ' + f.replace('.', '\\.') + '$', 'm'), 'deployed: ' + f);
    assert.match(editor, new RegExp('<script src="' + f.replace('.', '\\.') + '\\?v=[\\d.]+"></script>'), 'editor loads ' + f);
  }
  assert.match(editor, /<html lang="en" data-bf-text="off">/, 'the editor shows originals, not its own edits');
  assert.match(editor, /id="export"/); assert.match(editor, /id="import"/); assert.match(editor, /data-act="reset"/);
});
